use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Scan all Cargo.toml files in workspace and collect their dependencies"] pub fn collect_all_workspace_dependencies (workspace_dir : & Path) -> Result < HashMap < String , Value > > { let mut all_deps = HashMap :: new () ; for entry in WalkDir :: new (workspace_dir) . max_depth (2) { let entry = entry ? ; let path = entry . path () ; if path . file_name () == Some (std :: ffi :: OsStr :: new ("Cargo.toml")) && path != workspace_dir . join ("Cargo.toml") { if let Ok (manifest) = crate :: manifest :: read_manifest (path) { let deps = crate :: dependencies :: collect_dependencies (& manifest) ; for (name , _value) in deps { let mut workspace_entry = toml :: map :: Map :: new () ; let wrapped_path = if name == "alloc" { "./wrapped-rustc-std-workspace-alloc" . to_string () } else { format ! ("./wrapped-{}" , name) } ; workspace_entry . insert ("path" . to_string () , Value :: String (wrapped_path)) ; all_deps . insert (name , Value :: Table (workspace_entry)) ; } } } } Ok (all_deps) }